public function testTranslatedAttributeNamesAreReplacedInArraysFromNestedRules()
{
    $trans = $this->getIlluminateArrayTranslator();
    $trans->addLines([
        'validation.required' => ':attribute is required!',
        'validation.attributes' => ['users.*.id' => 'User ID'],
    ], 'en');
